CREATE OR REPLACE PROCEDURE HARNESS_APP.archive_old_orders(
    p_order_date DATE
)
IS
    TYPE t_rows IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
    l_rows       t_rows;
    c_batch_size CONSTANT PLS_INTEGER := 10000;

    CURSOR c_old_orders IS
        SELECT ORDER_ID,
               CUSTOMER_ID,
               ORDER_DATE,
               STATUS,
               TOTAL
          FROM HARNESS_APP.ORDERS
         WHERE ORDER_DATE < p_order_date;
BEGIN
    OPEN c_old_orders;

    LOOP
        FETCH c_old_orders BULK COLLECT INTO l_rows LIMIT c_batch_size;
        EXIT WHEN l_rows.COUNT = 0;

        FORALL i IN INDICES OF l_rows
            INSERT INTO HARNESS_APP.ORDERS_ARCHIVE (
                ORDER_ID,
                CUSTOMER_ID,
                ORDER_DATE,
                STATUS,
                TOTAL
            )
            VALUES (
                l_rows(i).ORDER_ID,
                l_rows(i).CUSTOMER_ID,
                l_rows(i).ORDER_DATE,
                l_rows(i).STATUS,
                l_rows(i).TOTAL
            );

        FORALL i IN INDICES OF l_rows
            DELETE FROM HARNESS_APP.ORDERS
             WHERE ORDER_ID = l_rows(i).ORDER_ID;
    END LOOP;

    CLOSE c_old_orders;
EXCEPTION
    WHEN OTHERS THEN
        IF c_old_orders%ISOPEN THEN
            CLOSE c_old_orders;
        END IF;
        RAISE;
END archive_old_orders;
/
