DECLARE
  l_savepoint_name        VARCHAR2(30) := 'TEST_HEADCOUNT_SP';
  l_failures              PLS_INTEGER := 0;

  l_existing_dept         NUMBER;
  l_existing_expected     NUMBER;
  l_existing_actual       NUMBER;

  l_missing_dept          NUMBER;
  l_missing_candidate_cnt NUMBER;
  l_missing_expected      NUMBER;
  l_missing_actual        NUMBER;

  l_null_expected         NUMBER := 0;
  l_null_actual           NUMBER;

  PROCEDURE report_check(
    p_check_name IN VARCHAR2,
    p_expected   IN VARCHAR2,
    p_actual     IN VARCHAR2,
    p_passed     IN BOOLEAN
  ) IS
  BEGIN
    IF p_passed THEN
      DBMS_OUTPUT.PUT_LINE('PASS: ' || p_check_name ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
    ELSE
      DBMS_OUTPUT.PUT_LINE('FAIL: ' || p_check_name ||
                           ' expected=' || p_expected ||
                           ' actual=' || p_actual);
      l_failures := l_failures + 1;
    END IF;
  END report_check;
BEGIN
  SAVEPOINT test_headcount_sp;

  -- Check 1: a department_id that has at least one employee.
  SELECT MIN(department_id)
    INTO l_existing_dept
    FROM employees
   WHERE department_id IS NOT NULL;

  IF l_existing_dept IS NULL THEN
    report_check(
      p_check_name => 'existing department_id',
      p_expected   => 'a non-null department_id with employees',
      p_actual     => 'no suitable row found in employees',
      p_passed     => FALSE
    );
  ELSE
    SELECT COUNT(*)
      INTO l_existing_expected
      FROM employees
     WHERE department_id = l_existing_dept;

    l_existing_actual := HARNESS_APP.headcount(l_existing_dept);

    report_check(
      p_check_name => 'existing department_id',
      p_expected   => TO_CHAR(l_existing_expected),
      p_actual     => TO_CHAR(l_existing_actual),
      p_passed     => l_existing_actual = l_existing_expected
    );
  END IF;

  -- Check 2: a non-null department_id that matches no employee row.
  SELECT MIN(candidate_dept)
    INTO l_missing_dept
    FROM (
      SELECT -1 AS candidate_dept FROM dual
      UNION ALL
      SELECT MIN(department_id) - 1
        FROM employees
       WHERE department_id IS NOT NULL
    ) candidates
   WHERE NOT EXISTS (
           SELECT 1
             FROM employees e
            WHERE e.department_id = candidates.candidate_dept
         );

  IF l_missing_dept IS NULL THEN
    report_check(
      p_check_name => 'non-matching department_id',
      p_expected   => '0',
      p_actual     => 'no suitable non-matching department_id found',
      p_passed     => FALSE
    );
  ELSE
    SELECT COUNT(*)
      INTO l_missing_candidate_cnt
      FROM employees
     WHERE department_id = l_missing_dept;

    IF l_missing_candidate_cnt <> 0 THEN
      report_check(
        p_check_name => 'non-matching department_id',
        p_expected   => '0',
        p_actual     => 'candidate matched rows: ' ||
                        TO_CHAR(l_missing_candidate_cnt),
        p_passed     => FALSE
      );
    ELSE
      l_missing_expected := 0;
      l_missing_actual := HARNESS_APP.headcount(l_missing_dept);

      report_check(
        p_check_name => 'non-matching department_id',
        p_expected   => TO_CHAR(l_missing_expected),
        p_actual     => TO_CHAR(l_missing_actual),
        p_passed     => l_missing_actual = l_missing_expected
      );
    END IF;
  END IF;

  -- Check 3: NULL argument. The function compares department_id = p_department_id,
  -- so a NULL argument matches no rows and should return 0.
  l_null_actual := HARNESS_APP.headcount(NULL);

  report_check(
    p_check_name => 'NULL department_id',
    p_expected   => TO_CHAR(l_null_expected),
    p_actual     => TO_CHAR(l_null_actual),
    p_passed     => l_null_actual = l_null_expected
  );

  ROLLBACK TO test_headcount_sp;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed: ' || l_failures || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('ERROR: ' || SQLERRM);
    ROLLBACK TO test_headcount_sp;
    RAISE;
END;
```

The block calls the stored function as `HARNESS_APP.headcount` rather than copying its source into the test. It checks three cases: a non-null `department_id` that has at least one employee, a non-null `department_id` that matches no employee row, and a `NULL` argument. For the existing department case, it finds a non-null `department_id` from `employees`, computes the expected count independently with `COUNT(*)`, calls the function, and compares the result. If no suitable row exists, it reports `FAIL` and counts the failure.

For the non-matching case, it tries to find a candidate value that is not present in `employees`, confirms with `COUNT(*)` that no employee row has that `department_id`, then expects the function to return `0`. If no suitable non-matching candidate can be found, or if the candidate unexpectedly matches rows, the check reports `FAIL`.

For the `NULL` case, the expected result is `0` because the function uses `department_id = p_department_id`, and equality with `NULL` matches no rows. The block starts with a savepoint, rolls back to it at the end, and also rolls back to it and re-raises in the exception handler. It does not commit. I have not run this block, and it has not been compiled or executed against the database.

